 37→
 38→/** Unions authorization_details from multiple intents into a flat EffectiveScope. */
 39→export function computeEffectiveScope(
 40→  intents: readonly AuthorizedIntentSummary[],
 41→): EffectiveScope {
 42→  const authorizedActions = intents.flatMap(
 43→    (intent) => intent.authorizationDetails,
 44→  );
 45→  return { authorizedActions, intents };
 46→}
 47→
 48→/**
 49→ * Build the resource string used for matching actions to tools.
 50→ * Format: `mcp_tool:{toolkit}:{toolName}`
 51→ */
 52→function buildToolResource(toolkit: string, toolName: string): string {
 53→  return `mcp_tool:${toolkit}:${toolName}`;
 54→}
 55→
 56→/** Find the first intent whose authorization_details contain a matching resource. */
 57→function findMatchingIntent(
 58→  toolResource: string,
 59→  effectiveScope: EffectiveScope,
 60→): AuthorizedIntentSummary | undefined {
 61→  return effectiveScope.intents.find((intent) =>
 62→    intent.authorizationDetails.some(
 63→      (action) => action.resource === toolResource,
 64→    ),
 65→  );
 66→}
 67→
 68→/** Classify a single tool against the effective scope and osabio-native set. */
 69→function classifyTool(
 70→  tool: ResolvedTool,
 71→  effectiveScope: EffectiveScope,
 72→  osabioNativeToolNames: ReadonlySet<string>,
 73→): ToolClassification {
 74→  if (osabioNativeToolNames.has(tool.name)) {
 75→    return { kind: "osabio_native" };
 76→  }
 77→
 78→  const toolResource = buildToolResource(tool.toolkit, tool.name);
 79→  const matchingIntent = findMatchingIntent(toolResource, effectiveScope);
 80→
 81→  if (matchingIntent) {
 82→    return { kind: "authorized", matchingIntent };
 83→  }
 84→
 85→  return { kind: "gated" };
 86→}
 87→
 88→/**
 89→ * Compute the set of osabio write tools that have an approved intent.
 90→ * Checks for resources matching `mcp_tool:osabio:{toolName}`.
 91→ */
 92→export function computeAuthorizedBrainWriteTools(
 93→  effectiveScope: EffectiveScope,
 94→  osabioWriteToolNames: ReadonlySet<string>,
 95→): ReadonlySet<string> {
 96→  const authorized = new Set<string>();
 97→  for (const toolName of osabioWriteToolNames) {
 98→    const resource = `mcp_tool:osabio:${toolName}`;
 99→    if (effectiveScope.authorizedActions.some((a) => a.resource === resource)) {
100→      authorized.add(toolName);
101→    }
102→  }
103→  return authorized;
104→}
105→
106→/**
107→ * Find the first intent whose authorization_details match an osabio write tool.
108→ * Returns the intent summary or undefined if no match.
109→ */
110→export function findBrainWriteIntent(
111→  toolName: string,
112→  effectiveScope: EffectiveScope,
113→): AuthorizedIntentSummary | undefined {
114→  const resource = `mcp_tool:osabio:${toolName}`;
115→  return effectiveScope.intents.find((intent) =>
116→    intent.authorizationDetails.some((action) => action.resource === resource),
117→  );
118→}
119→
120→/** Classifies each granted tool as authorized, gated, or osabio_native. */
121→export function classifyTools(
122→  grantedTools: readonly ResolvedTool[],
123→  effectiveScope: EffectiveScope,
124→  osabioNativeToolNames: ReadonlySet<string>,
125→): readonly ClassifiedTool[] {
126→  return grantedTools.map((tool) => ({
127→    tool,
128→    classification: classifyTool(tool, effectiveScope, osabioNativeToolNames),
129→  }));
130→}
