 50→function nonEmpty(value: string | undefined): string | undefined {
 51→  if (value === undefined) return undefined;
 52→  const trimmed = value.trim();
 53→  return trimmed.length > 0 ? trimmed : undefined;
 54→}
 55→
 56→function parseNumber(value: string | undefined): number | undefined {
 57→  const normalized = nonEmpty(value);
 58→  if (!normalized) return undefined;
 59→  const parsed = Number(normalized);
 60→  if (!Number.isFinite(parsed)) return undefined;
 61→  return parsed;
 62→}
 63→
 64→function parseJsonWebKey(value: string | undefined): JsonWebKey | undefined {
 65→  const normalized = nonEmpty(value);
 66→  if (!normalized) return undefined;
 67→  try {
 68→    return JSON.parse(normalized) as JsonWebKey;
 69→  } catch {
 70→    return undefined;
 71→  }
