 77→
 78→/**
 79→ * Find the main repository root from any path, including worktrees.
 80→ *
 81→ * In a regular repo, `.git` is a directory → that dir is the root.
 82→ * In a worktree, `.git` is a file containing `gitdir: /path/to/main/.git/worktrees/<name>`.
 83→ * We follow the pointer back to the main repo so all worktrees share one config key.
 84→ */
 85→export function findGitRoot(from: string): string | undefined {
 86→  let dir = from;
 87→  while (dir !== "/") {
 88→    const gitPath = join(dir, ".git");
 89→    if (existsSync(gitPath)) {
 90→      if (statSync(gitPath).isFile()) {
 91→        return resolveWorktreeMainRoot(gitPath) ?? dir;
 92→      }
 93→      return dir;
 94→    }
 95→    dir = dirname(dir);
 96→  }
 97→  return undefined;
 98→}
 99→
100→/** Read a worktree .git file and resolve to the main repo root. */
101→function resolveWorktreeMainRoot(gitFile: string): string | undefined {
102→  try {
103→    const content = Bun.file(gitFile).textSync().trim();
104→    const match = content.match(/^gitdir:\s*(.+)$/);
105→    if (!match) return undefined;
106→
107→    const gitdir = resolve(dirname(gitFile), match[1]);
108→    const dotGit = gitdir.replace(/\/worktrees\/[^/]+$/, "");
109→    return dirname(dotGit);
110→  } catch {
111→    return undefined;
112→  }
113→}
