 83→function normalizeTokens(value: string): Set<string> {
 84→  return new Set(
 85→    value
 86→      .toLowerCase()
 87→      .replace(/[^a-z0-9\s]/g, " ")
 88→      .split(/\s+/)
 89→      .map((t) => t.trim())
 90→      .filter((t) => t.length > 2),
